namespace CallbackAfter
{
    public class Counter
    {
        private Action<int> onChange;
        private int total;
        public Counter()
        {
            total = 0;
            onChange = Report;
        }
        private void Report(int value)
        {
            Console.WriteLine(value);
        }
        public void Bump(int n)
        {
